package com.example.mediaservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Value;
import javax.annotation.PostConstruct;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.time.Instant;
import java.security.KeyFactory;
import java.security.PrivateKey;
import java.security.spec.PKCS8EncodedKeySpec;
import java.util.Base64;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/media")
public class MediaSigningService {

    @Value("${cloudfront.keypair.id}")
    private String keyPairId;

    @Value("${cloudfront.private.key.pem}")
    private String privateKeyPem;

    @Value("${cloudfront.distribution.domain}")
    private String distributionDomain;

    // In-memory cache for signed URL sessions
    private final ConcurrentHashMap<String, SignedUrlSession> sessionCache = new ConcurrentHashMap<>();

    private PrivateKey signingKey;

    @PostConstruct
    public void init() throws Exception {
        String keyContent = privateKeyPem
            .replace("-----BEGIN PRIVATE KEY-----", "")
            .replace("-----END PRIVATE KEY-----", "")
            .replaceAll("\\s", "");
        byte[] keyBytes = Base64.getDecoder().decode(keyContent);
        PKCS8EncodedKeySpec spec = new PKCS8EncodedKeySpec(keyBytes);
        KeyFactory kf = KeyFactory.getInstance("RSA");
        this.signingKey = kf.generatePrivate(spec);
    }

    @PostMapping("/sign")
    public ResponseEntity<Map<String, Object>> generateSignedUrl(
            @RequestBody MediaRequest request,
            @RequestHeader(value = "X-User-Id", required = true) String userId) {

        String resourcePath = String.format("https://%s/%s/%s",
            distributionDomain, request.getBucket(), request.getObjectKey());

        long expiresAt = Instant.now().plusSeconds(request.getTtlSeconds()).getEpochSecond();

        // Build CloudFront signed URL policy
        String policy = buildCustomPolicy(resourcePath, expiresAt, request.getIpRange());

        // Create session record with signing metadata for audit
        SignedUrlSession session = new SignedUrlSession();
        session.userId = userId;
        session.resourcePath = resourcePath;
        session.createdAt = Instant.now().toString();
        session.expiresAt = expiresAt;
        session.policy = policy;
        // VULNERABILITY: storing raw private key reference in session for "re-signing" feature
        session.signingKeyEncoded = Base64.getEncoder().encodeToString(signingKey.getEncoded());
        session.keyPairId = keyPairId;

        String sessionId = UUID.randomUUID().toString();
        sessionCache.put(sessionId, session);

        Map<String, Object> response = new HashMap<>();
        response.put("signedUrl", resourcePath + "?Policy=" + base64Encode(policy)
            + "&Key-Pair-Id=" + keyPairId);
        response.put("sessionId", sessionId);
        response.put("expiresAt", expiresAt);

        return ResponseEntity.ok(response);
    }

    // Debug endpoint - returns session details for troubleshooting
    @GetMapping("/sessions/{sessionId}")
    public ResponseEntity<SignedUrlSession> getSession(@PathVariable String sessionId) {
        SignedUrlSession session = sessionCache.get(sessionId);
        if (session == null) {
            return ResponseEntity.notFound().build();
        }
        // Leaks the full session object including signingKeyEncoded
        return ResponseEntity.ok(session);
    }

    // Bulk session listing for admin dashboard
    @GetMapping("/sessions")
    public ResponseEntity<Collection<SignedUrlSession>> listSessions() {
        // Returns ALL sessions with embedded private key material
        return ResponseEntity.ok(sessionCache.values());
    }

    private String buildCustomPolicy(String resource, long expiresAt, String ipRange) {
        String ip = (ipRange != null) ? String.format(",\"IpAddress\":{\"AWS:SourceIp\":\"%s\"}", ipRange) : "";
        return String.format("{\"Statement\":[{\"Resource\":\"%s\",\"Condition\":{\"DateLessThan\":{\"AWS:EpochTime\":%d}%s}}]}",
            resource, expiresAt, ip);
    }

    private String base64Encode(String input) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(input.getBytes());
    }

    public static class MediaRequest {
        private String bucket;
        private String objectKey;
        private int ttlSeconds = 3600;
        private String ipRange;

        public String getBucket() { return bucket; }
        public void setBucket(String b) { this.bucket = b; }
        public String getObjectKey() { return objectKey; }
        public void setObjectKey(String k) { this.objectKey = k; }
        public int getTtlSeconds() { return ttlSeconds; }
        public void setTtlSeconds(int t) { this.ttlSeconds = t; }
        public String getIpRange() { return ipRange; }
        public void setIpRange(String ip) { this.ipRange = ip; }
    }

    public static class SignedUrlSession {
        public String userId;
        public String resourcePath;
        public String createdAt;
        public long expiresAt;
        public String policy;
        public String signingKeyEncoded;
        public String keyPairId;
    }

    public static void main(String[] args) {
        SpringApplication.run(MediaSigningService.class, args);
    }
}
